def transform(grid):
    """Tile 8-cells with 2x2 squares and L-triominoes; color by shape."""
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= occupied:
                tiles.append((box, 1))
            for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = box - {missing}
                if shape <= occupied:
                    tiles.append((shape, color))

    by_cell = {p: [] for p in occupied}
    for shape, color in tiles:
        for p in shape:
            by_cell[p].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    tiling = cover(occupied)
    if tiling is None:
        raise ValueError('No valid square/L-triomino tiling')
    out = [[0] * w for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
